27	/// When a spell fizzles, the engine should NOT emit SpellResolved.
28	/// A fizzled spell was countered by game rules — it did not resolve.
29	#[test]
30	fn fizzled_spell_does_not_emit_resolved_event() {
31	    let reg = registry();
32	    let mut state = game_at_step(Step::PrecombatMain, P0);
33	
34	    let creature = ready_creature(&mut state, P1, 3, 3);
35	    let bolt = castable_spell(&mut state, &reg, "Lightning Bolt", P0);
36	
37	    state = engine::submit_action(
38	        &state,
39	        &Action::CastSpell { object_id: bolt, targets: vec![Target::Object(creature)], sacrifice: None, exile_count: None, alternative_cost: None },
40	        &reg,
41	    );
42	
43	    // Target dies before resolution.
44	    state.move_object(creature, Zone::Graveyard);
45	    state.events.clear();
46	
47	    mtg_engine::stack::resolve_top_of_stack(&mut state, &reg);
48	
49	    // Should NOT have a SpellResolved event — the spell fizzled.
50	    let has_resolved = state.events.iter().any(|e| {
51	        matches!(e, GameEvent::SpellResolved { object } if *object == bolt)
52	    });
53	    assert!(!has_resolved,
54	        "Fizzled spell should NOT emit SpellResolved — it was countered by game rules, not resolved (CR 608.2b)");
55	}
